package com.axiom.application.analysis;
import com.axiom.analysis.logs.*; import com.axiom.domain.failure.FailureEvent; import com.axiom.logstorage.LogStorage; import java.nio.charset.StandardCharsets; import java.util.*; import java.util.zip.*; import java.io.*; import java.util.UUID; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class PipelineLogAnalysisService { private final LogStorage storage;private final LogNormalizer normalizer;private final FailureEventExtractor extractor;private final JdbcTemplate jdbc; public PipelineLogAnalysisService(LogStorage s,LogNormalizer n,FailureEventExtractor e,JdbcTemplate j){storage=s;normalizer=n;extractor=e;jdbc=j;}
 @Transactional public Map<String,Object> process(UUID id){byte[] bytes=storage.load(id).orElseThrow(()->new IllegalArgumentException("No stored log for pipeline run "+id));String text=decode(bytes);var events=normalizer.normalize(text);var failures=extractor.extract(events);jdbc.update("delete from failure_events where pipeline_run_id=?",id);for(FailureEvent f:failures)jdbc.update("insert into failure_events(id,pipeline_run_id,event_type,exception_type,raw_message,normalized_message,stack_trace,normalized_stack_root,fingerprint,fingerprint_algorithm,occurrence_count,first_line,last_line) values (?,?,?,?,?,?,?,?,?,?,?,?,?)",UUID.randomUUID(),id,f.type().name(),f.exceptionType(),f.rawMessage(),f.normalizedMessage(),f.stackTrace(),f.normalizedStackRoot(),f.fingerprint(),"v1",f.occurrences(),f.firstLine(),f.lastLine());return Map.of("pipelineRunId",id,"logFilesProcessed",1,"logEventsDetected",events.size(),"failureOccurrences",failures.stream().mapToInt(FailureEvent::occurrences).sum(),"uniqueFailureCount",failures.size());}
 private String decode(byte[] bytes){if(bytes.length>3&&bytes[0]=='P'&&bytes[1]=='K')try(ZipInputStream zip=new ZipInputStream(new ByteArrayInputStream(bytes))){StringBuilder s=new StringBuilder();int count=0;ZipEntry e;byte[] buf=new byte[8192];while((e=zip.getNextEntry())!=null){if(++count>5000||e.isDirectory()||e.getName().startsWith("/")||e.getName().contains(".."))continue;int read,total=0;while((read=zip.read(buf))>0){if((total+=read)>25_000_000)break;s.append(new String(buf,0,read,StandardCharsets.UTF_8));}s.append('\n');}return s.toString();}catch(IOException e){throw new IllegalArgumentException("Stored log archive could not be safely decoded",e);}return new String(bytes,StandardCharsets.UTF_8);}
}
